"""Generate the auditable exercise/source/measurement matrix from shipped rules."""
import csv
import io
import json
from pathlib import Path

ROOT=Path(__file__).resolve().parents[1]

def render():
    catalog=json.loads((ROOT/'core-motion/src/main/resources/ai/senp/motion/exercise-techniques.json').read_text())
    sources={s['id']:s for s in catalog['sources']}
    lines=['# Exercise technique coverage','',
           'Generated by `python scripts/report_exercise_techniques.py`. Explicit exercise selection and a usable reference are required. '
           'A catalogue entry is a rule binding, not independently measured accuracy for that exercise. '
           'Reference ranges reproduce the chosen demonstration; source targets are separate. Trigger margins are engineering settings.',
           '',f"{len(catalog['exercises'])} exercise/variant IDs; {len(sources)} sources; {sum(len(e['rules']) for e in catalog['exercises'])} rules; 25 measurable features.",
           '', '| Exercise ID | Reference measurements | Source targets (degrees unless stated) | Sources |',
           '| --- | --- | --- | --- |']
    out=io.StringIO(newline='');writer=csv.writer(out)
    writer.writerow(['exercise_id','name','family','rule_id','mode','phase','anchor','features','lower','upper','enter_margin','exit_margin','summary','cue','limitations','source_urls'])
    for exercise in catalog['exercises']:
        refs=set();targets=[];links={}
        for rule in exercise['rules']:
            if rule['mode']=='REFERENCE_RANGE':refs.update(rule['features'])
            if rule['mode']=='SOURCE_TARGET':
                targets.append(', '.join(rule['features'])+f" = {rule['lower']}..{rule['upper']} ({rule['phase'].lower()}; enter {rule['enter']}, exit {rule['exit']})")
            for source in rule['sources']:links[source]=sources[source]
            writer.writerow([exercise['id'],exercise['name'],exercise['family'],rule['id'],rule['mode'],rule['phase'],rule.get('anchor',''),
                '; '.join(rule['features']),rule.get('lower',''),rule.get('upper',''),rule.get('enter',''),rule.get('exit',''),
                rule['summary'],rule['cue'],rule['limitation']+' '+' '.join(exercise['limitations']),'; '.join(sources[s]['url'] for s in rule['sources'])])
        refs_text=', '.join(sorted(refs)).replace('angle.','').replace('distance.','').replace('relation.','')
        lines.append(f"| `{exercise['id']}` | {refs_text or 'None'} | {'; '.join(targets) or 'None'} | "+', '.join(f"[{s['publisher']}]({s['url']})" for s in links.values())+' |')
    lines.extend(['','All entries explicitly exclude properties not observable from these landmarks. Breathing, pain, muscle activation, force/load and detailed spinal curvature need other measurements. Width ratios are spacing proxies, not knee-over-toe or foot-pressure measurements.',
                  '', 'Standing side bend is identified by dataset metadata and uses reference comparison only. That dataset does not publish prescriptive technique rules.',
                  '', '## Source index',''])
    for s in sources.values():lines.append(f"- `{s['id']}`: [{s['publisher']} — {s['title']}]({s['url']}); retrieved {s['retrieved']}.")
    return '\n'.join(lines)+'\n',out.getvalue()

if __name__=='__main__':
    markdown,matrix=render()
    (ROOT/'docs/EXERCISE_TECHNIQUE_COVERAGE.md').write_text(markdown,encoding='utf-8')
    (ROOT/'docs/exercise-technique-rules.csv').write_text(matrix,encoding='utf-8',newline='')
    print('Generated coverage Markdown and rule CSV')
